type ResolveFilename = (request: string, parent: NodeModule | null | undefined, isMain: boolean, options?: unknown) => string;

type ModuleResolver = typeof Module & {
    _postcssInternalCompat?: boolean;
    _resolveFilename: ResolveFilename;
}

const postCSSInternalRequest = 'postcss/lib/';

const needsPostCSSInternalCompat = (): boolean => {
    try {
        require.resolve('postcss/lib/parser');

        return false;
    } catch (error) {
        const exception = error as NodeJS.ErrnoException;

        return exception.code === 'ERR_PACKAGE_PATH_NOT_EXPORTED';
    }
};

const patchPostCSSInternalResolution = () => {
    const moduleResolver = Module as ModuleResolver;

    if (moduleResolver._postcssInternalCompat || !needsPostCSSInternalCompat()) {
        return;
    }

    const resolveFilename = moduleResolver._resolveFilename;
    let postCSSLibPath: string | undefined;

    moduleResolver._resolveFilename = (request, parent, isMain, options) => {
        if (request.startsWith(postCSSInternalRequest)) {
            const requestedFile = request.slice(postCSSInternalRequest.length);
            const fileName = path.extname(requestedFile) ? requestedFile : `${requestedFile}.js`;

            if (fileName === 'parser.js') {
                return path.join(__dirname, 'postcss-parser-compat.js');
            }

            postCSSLibPath = postCSSLibPath || path.dirname(require.resolve('postcss'));

            return path.join(postCSSLibPath, fileName);
        }

        return resolveFilename.call(moduleResolver, request, parent, isMain, options);
    };

    moduleResolver._postcssInternalCompat = true;
};

